input.sparql:
SELECT ?p ?id WHERE {
  ?p ref:hasTimeseriesId ?id
  ?p a ?class .
  FILTER(str(?class) != "ref")
} LIMIT 50

SELECT ?b ?bname ?cls ?id WHERE {
  ?cls rdfs:subClassOf* brick:ElectricPower .
  ?point a ?cls .
  ?point ref:hasTimeseriesId ?id .
  ?b a brick:Building .
} LIMIT 50

SELECT ?pt ?cls ?id WHERE {
  ?pt a ?cls .
  FILTER(!isblank(?cls))
  OPTIONAL { ?pt ref:hasTimeseriesId ?id }
} ORDER BY ?cls LIMIT 200
